if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');if($action==='account'){$name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>190)throw new InvalidArgumentException('Kontobezeichnung erforderlich.');$pdo->prepare('INSERT INTO bank_accounts(name) VALUES(?)')->execute([$name]);gszAudit($pdo,(int)$_SESSION['admin_id'],'bank_account_created',['account_id'=>(int)$pdo->lastInsertId()]);}
 elseif($action==='preview'){$f=$_FILES['statement']??[];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>2*1024*1024||!in_array(strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)),['csv','xml'],true))throw new InvalidArgumentException('CSV-/CAMT-XML-Datei maximal2MB erforderlich.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['text/plain','text/csv','application/csv','text/xml','application/xml'],true))throw new InvalidArgumentException('Bankdatei muss CSV-/XML-Text sein.');$format=(string)($_POST['format']??'csv');if(($format==='camt'?'xml':'csv')!==strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)))throw new InvalidArgumentException('Dateiendung muss zum ausgewählten Format passen.');$map=['expected_iban'=>(string)($_POST['expected_iban']??'')];foreach(['booked_on','value_on','amount','currency','purpose','counterparty','id'] as $k)$map[$k]=(string)($_POST[$k]??'');$token=bankPreview($pdo,(int)$_SESSION['admin_id'],(int)($_POST['account_id']??0),file_get_contents($f['tmp_name']),$map,(string)($_POST['locale']??'de'),(string)($_POST['delimiter']??';'),(int)$config['bank_import_max_rows'],$format);redirect($back.'&import='.$token);}
 elseif($action==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Vorschau bestätigen.');bankApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''),!empty($_POST['possible_reviewed']));$_SESSION['app_notice']='Import übernommen; keine Zahlung ausgeführt und keine Buchung automatisch zugeordnet.';}
 else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){gszUiError($e);}redirect($back);}
$accounts=[];$rows=[];$preview=null;$ready=true;$search=mb_substr(trim((string)($_GET['q']??'')),0,100);try{$accounts=$pdo->query('SELECT a.id,a.name,a.currency,a.opening_balance_cents,a.opening_date,COALESCE(SUM(t.amount_cents),0) imported_sum FROM bank_accounts a LEFT JOIN bank_transactions t ON t.account_id=a.id GROUP BY a.id,a.name,a.currency,a.opening_balance_cents,a.opening_date ORDER BY a.id')->fetchAll();$q=$pdo->prepare('SELECT t.*,p.id payment_id FROM bank_transactions t LEFT JOIN finance_payments p ON p.allocation_key=t.id WHERE (?=0 OR t.account_id=?) AND (t.purpose LIKE ? OR t.counterparty LIKE ?) ORDER BY t.booked_on DESC,t.id DESC LIMIT 200');$q->execute([$account,$account,'%'.$search.'%','%'.$search.'%']);$rows=$q->fetchAll();if(isset($_GET['import'])){$q=$pdo->prepare('SELECT * FROM bank_imports WHERE token=? AND admin_id=?');$q->execute([(string)$_GET['import'],$_SESSION['admin_id']]);$preview=$q->fetch();}}catch(Throwable $e){$ready=false;$_SESSION['app_error']='Bank-/Finanzmigration erforderlich.';}
gszPageStart('Bankumsätze – nur Import');?><p>Onlinebanking <strong>nicht verbunden</strong>. Keine Überweisungsfunktion, keine PIN/TAN. Neutraler CSV-Import mit stabiler Quellen-ID oder begrenzter ISO20022-CAMT053/054-XML-Import. Reales Sparkassen-/Volksbank-Exportprofil noch nicht mit einer Bankdatei verifiziert. Keine MT940-Unterstützung. Stabile Quellen-ID ist Pflicht, damit identische legitime Umsätze nicht verschluckt werden.</p>
