<?php if($preview):$data=json_decode($preview['payload'],true,512,JSON_THROW_ON_ERROR);?><section class="card"><h2><?=e($preview['applied_at']?'Übernommener Bankimport – historische Vorschau':'Importvorschau – noch keine Umsätze gespeichert')?></h2><p>Dateihash <?=e($preview['file_hash'])?> · identisch vorhandene Zeilen <?=(int)$data['duplicates']?></p><?php foreach($data['conflicts'] as $c):?><p class="error">Abweichende Quellen-ID <?=e($c)?> – Übernahme gesperrt.</p><?php endforeach?><?php foreach($data['rows'] as $r):?><p><?=e($r['booked_on'].' · '.$r['counterparty'].' · '.financeDecimal((int)$r['amount_cents']).' EUR · '.$r['purpose'])?></p><?php endforeach?><?php if(!$preview['applied_at']):?><form method="post"><?php gszFields('apply');?><?php if(!empty($data['possible_duplicates'])):foreach($data['possible_duplicates'] as $candidate):?><p class="error">Ähnlicher Bestandsumsatz #<?=(int)$candidate['existing_id']?> · Referenz <?=e($candidate['existing_external'])?> / neu <?=e($candidate['incoming_external'])?>. Gleicher Betrag/Buchungstag ist keine sichere Dublette.</p><?php endforeach?><label><input type="checkbox" name="possible_reviewed" required> Bankbelege geprüft: tatsächlich verschiedene Umsätze, keine erneute Buchung derselben Bewegung beim Formatwechsel.</label><?php endif?><input type="hidden" name="token" value="<?=e($preview['token'])?>"><label><input type="checkbox" name="confirm" required> Quelle, Vorzeichen und Vorschau geprüft.</label><button <?=$data['conflicts']?'disabled':''?>>Bankimport bestätigen</button></form><?php endif?></section><?php endif?>
<form method="get"><label>Konto<select name="account"><option value="0">Alle</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$account===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach?></select></label><label>Suche<input name="q" maxlength="100" value="<?=e($search)?>"></label><button>Filtern</button></form><section class="card"><h2>Neueste 200 Umsätze</h2><?php foreach($rows as $r):?><article class="task-row"><strong><?=e($r['booked_on'].' · '.financeDecimal((int)$r['amount_cents']).' EUR')?></strong><p><?=e($r['counterparty'].' · '.$r['purpose'])?></p><p><?=$r['payment_id']?'Zuordnung bestätigt':'Beleg/Rechnungszuordnung fehlt'?> · <a href="accounting.php?transaction=<?=(int)$r['id']?>">Zuordnung prüfen</a></p></article><?php endforeach?></section>
<details class="card"><summary>CSV importieren</summary><form method="post" enctype="multipart/form-data"><?php gszFields('preview');?><label>Importformat<select name="format"><option value="csv">Neutrale CSV mit stabiler ID</option><option value="camt">CAMT053/054 (XML), nur gebuchte Einzelumsätze</option></select></label><label>Bei CAMT: vollständige IBAN des hier ausgewählten Kontos zum Abgleich<input name="expected_iban" autocomplete="off" maxlength="40"></label><p>CAMT benötigt PHP-DOM, eine stabile Bankreferenz und EUR; Sammelbuchungen/vorgemerkte Umsätze bleiben zur Prüfung gesperrt. CSV-Spaltenzuordnung wird bei CAMT ignoriert.</p><label>Konto<select name="account_id"><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?></option><?php endforeach?></select></label><label>CSV-/CAMT-XML-Datei<input type="file" name="statement" accept=".csv,.xml" required></label><label>Betragsformat<select name="locale"><option value="de">Deutsch: -1.234,56</option><option value="iso">ISO: -1234.56</option></select></label><label>Trennzeichen<select name="delimiter"><option value=";">Semikolon</option><option value=",">Komma</option></select></label><?php foreach(['booked_on'=>'datum','value_on'=>'valuta','amount'=>'betrag','currency'=>'waehrung','purpose'=>'zweck','counterparty'=>'gegenpartei','id'=>'id'] as $key=>$default):?><label>Spaltenname <?=e($key)?><input name="<?=e($key)?>" value="<?=e($default)?>"></label><?php endforeach?><button>Importvorschau erstellen</button></form></details><details class="card"><summary>Importkonto anlegen</summary><form method="post"><?php gszFields('account');?><label>Interne Bezeichnung, keine Zugangsdaten<input name="name" maxlength="190" required></label><button>Importkonto speichern</button></form></details><?php endif?><?php gszPageEnd();?>
